#[cfg(test)]
mod codex_m2_semantic_rereview {
 use super::*;
 struct Fixture(PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
 fn fixture()->(Fixture,Connection){let root=std::env::temp_dir().join(format!("m2-codex-rereview-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir_all(&root).unwrap();let c=Connection::open(root.join("her-flight-deck.db")).unwrap();c.pragma_update(None,"foreign_keys","ON").unwrap();for m in crate::migrations(){c.execute_batch(m.sql).unwrap();}c.execute_batch("CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY);INSERT INTO schema_migrations VALUES(11);INSERT INTO study_materials(id,title,created_at,updated_at) VALUES('mat','Synthetic','2026-10-04','2026-10-04');").unwrap();crate::practice_sessions::save_practice_test_at(&root,"mat","Synthetic",r#"[{"question":"Synthetic","options":["A","B"],"correctIndex":0,"explanation":"","sourcePage":null}]"#,"synthetic").unwrap();(Fixture(root),c)}
 fn start(f:&Fixture,c:&Connection)->serde_json::Value {let v:String=c.query_row("SELECT id FROM practice_test_versions",[],|r|r.get(0)).unwrap();crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"start_or_resume","operationId":"20000000-0000-4000-8000-000000000001","materialId":"mat","versionId":v})).unwrap()}
 fn record(f:&Fixture,c:&Connection,s:&serde_json::Value){let i:String=c.query_row("SELECT id FROM practice_test_items",[],|r|r.get(0)).unwrap();crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"record_response","operationId":"20000000-0000-4000-8000-000000000002","attemptId":s["attemptId"],"itemId":i,"expectedRevision":0,"selectedIndex":1,"isDontKnow":false})).unwrap();}
 #[test]fn receipt_empty_object_refused(){let(f,c)=fixture();start(&f,&c);c.execute_batch("UPDATE practice_session_operations SET result_json='{}'").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"empty-object result was accepted");}
 #[test]fn out_of_range_stored_response_refused(){let(f,c)=fixture();let s=start(&f,&c);record(&f,&c,&s);c.execute_batch("UPDATE practice_responses SET selected_index=99").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"selected_index=99 for two options was accepted");}
 #[test]fn cross_material_attempt_refused(){let(f,c)=fixture();start(&f,&c);c.execute_batch("INSERT INTO study_materials(id,title,created_at,updated_at) VALUES('other','Other synthetic','2026-10-04','2026-10-04');UPDATE practice_attempts SET source_material_id='other'").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"cross-material attempt owner was accepted");}
 #[test]fn counterfeit_unique_index_refused(){let(f,c)=fixture();c.execute_batch("DROP INDEX uq_single_in_progress_attempt;CREATE INDEX uq_single_in_progress_attempt ON practice_attempts(source_material_id)").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"same-name nonunique replacement was accepted");}
 #[test]fn missing_version_column_refused(){let(f,c)=fixture();c.execute_batch("ALTER TABLE practice_test_versions DROP COLUMN model").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"missing version model column was accepted");}
 #[test]fn null_completed_score_refused(){let(f,c)=fixture();let s=start(&f,&c);record(&f,&c,&s);crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"complete_attempt","operationId":"20000000-0000-4000-8000-000000000003","attemptId":s["attemptId"],"expectedRevision":1})).unwrap();c.execute_batch("UPDATE practice_attempts SET score_percent=NULL").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"null completed score was accepted");}
}
